import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { createMeetingsClient } from "../src/meetings/client.ts";

// Original-evidence expectations are immutable, never regenerated by the client.
const manifestSha256 = "85667dab73fb1180fddb99c7dd2435a88e46d6f863b3122626e5109372942ed6";
const corpus = process.env.TOWNLIGHT_CONNECTOR_BASELINE;
let sources;
if (corpus) {
  const bytes = await readFile(resolve(corpus, "cases.json"));
  assert.equal(createHash("sha256").update(bytes).digest("hex"), manifestSha256);
  sources = JSON.parse(bytes).map(({ connector, input_format, source_url }) => ({
    connector, input_format, source_url,
  }));
  assert.equal(sources.length, 34);
  assert.equal(new Set(sources.map(source => source.connector)).size, 31);
} else {
  sources = [{
    connector: "first-party", input_format: "public-meeting-ics",
    source_url: "https://council.example.org/calendar.ics",
  }];
  console.log("NOT_RUN: Set TOWNLIGHT_CONNECTOR_BASELINE for all 34 adapter cases.");
}

const calls = [];
const unchanged = {
  status: "unchanged", meeting_id: "11111111-1111-4111-8111-111111111111",
  agenda_item_ids: ["22222222-2222-4222-8222-222222222222"],
  source_key: "a".repeat(64),
};
const client = createMeetingsClient(async (command, { request }) => {
  calls.push({ command, request });
  return request.operation === "commit-import" ? unchanged : {};
});
for (const { source_url, ...source } of sources) {
  const start = calls.length;
  const payload = { ...source, source_url, content_base64: "e30=" };
  await client.fetchImport({ ...source, actor: "forged", service_url: "https://wrong.example.org" }, source_url);
  await client.previewImport(payload);
  assert.equal(calls.length, start + 2, "Fetch/preview must not implicitly commit.");
  assert.deepEqual(calls[start], {
    command: "meetings_domain_request",
    request: { operation: "fetch-import", payload: { ...source, source_url } },
  });
  assert.deepEqual(calls[start + 1], {
    command: "meetings_domain_request", request: { operation: "preview-import", payload },
  });
  const result = await client.commitImport(payload, "meeting-α", "b".repeat(64));
  assert.equal(result, unchanged);
  assert.deepEqual(calls[start + 2], {
    command: "meetings_domain_request",
    request: { operation: "commit-import", payload: {
      ...payload, external_id: "meeting-α", expected_sha256: "b".repeat(64),
    } },
  });
}
assert.equal(calls.length, sources.length * 3);
let attempts = 0;
const failed = createMeetingsClient(async () => {
  attempts++;
  throw { code: "service-unavailable", outcome_unknown: true };
});
await assert.rejects(failed.commitImport({
  connector: "legistar", input_format: "meeting-export",
  source_url: "https://council.example.org/export", content_base64: "e30=",
}, "meeting-α", "b".repeat(64)));
assert.equal(attempts, 1, "An uncertain canonical commit must not retry in the native client.");
console.log(`PASS: ${sources.length} Meetings format adapters preserve explicit commit, canonical IDs and no-retry behavior.`);
